function preloader(){$("#preloader").fadeToggle()}function parseValidator(n){$(n).data("validator",null);$.validator.unobtrusive.parse($(n))}function goUp(){$("html, body").animate({scrollTop:0},500)}function uiAlert(n,t){UIkit.notification.closeAll();UIkit.notification({message:n,status:t,pos:"bottom-center",timeout:1e4})}function submitForm(n){$(n).valid()==!0&&(preloader(),$(n).submit())}function getdate(){var r=new Date,n=r.getHours(),t=r.getMinutes(),i=r.getSeconds();i<10&&(i="0"+i);t<10&&(t="0"+t);n<10&&(n="0"+n);$(".main-clock").text(n+":"+t+":"+i);setTimeout(function(){getdate()},500)}function getNotifications(){$.post("/admin/admin-notifications",{},function(n){n.sum>0&&$("#notification-icon > a").prepend('<span class="uk-position-absolute heartbeat"><\/span>');$("#n-contact").text(n.contacts)},"json")}function numberWithCommas(n){return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g,",")}function checkboxBoolean(n){$(n).val($(n).is(":checked"))}$(document).ready(function(){new StickySidebar("#sidebar",{containerSelector:"#main-content",innerWrapperSelector:"#sidebar-inner",topSpacing:60,bottomSpacing:0});getdate();getNotifications()});$(document).on("keyup",".format-number",function(){var t=$(this).val();let n=$(this).parent();n.hasClass("appended")||(n.append('<div class="format-append uk-text-left uk-text-light uk-font-sm"><\/div>'),n.addClass("appended"));n.find(".format-append").text(numberWithCommas(t))});